// Package lease provides a concurrency-safe in-memory lease manager.
package lease

import (
	"errors"
	"fmt"
	"sort"
	"sync"
	"time"
)

// Token uniquely identifies a lease. Tokens are generated by the Manager and
// are never reused within the lifetime of that Manager.
type Token string

// Lease describes a single active lease on a resource.
type Lease struct {
	Key       string
	Owner     string
	Token     Token
	ExpiresAt time.Time
}

var (
	ErrInvalidTTL    = errors.New("lease: ttl must be positive")
	ErrEmptyKey      = errors.New("lease: key must not be empty")
	ErrEmptyOwner    = errors.New("lease: owner must not be empty")
	ErrLeaseHeld     = errors.New("lease: resource already has an active lease")
	ErrLeaseNotFound = errors.New("lease: no active lease for key")
	ErrOwnerMismatch = errors.New("lease: owner does not match the active lease")
	ErrTokenMismatch = errors.New("lease: token does not match the active lease")
)

// Manager issues, renews, and releases leases. At most one active lease
// exists per key at any time. It is safe for concurrent use.
type Manager struct {
	mu     sync.Mutex
	ttl    time.Duration
	clock  Clock
	leases map[string]Lease
	nextID uint64
}

// Option configures a Manager.
type Option func(*Manager)

// WithClock sets the clock used for expiry decisions. The default is the
// system wall clock.
func WithClock(c Clock) Option {
	return func(m *Manager) { m.clock = c }
}

// NewManager creates a Manager that grants leases with the given ttl.
// The ttl must be positive.
func NewManager(ttl time.Duration, opts ...Option) (*Manager, error) {
	if ttl <= 0 {
		return nil, ErrInvalidTTL
	}
	m := &Manager{
		ttl:    ttl,
		clock:  realClock{},
		leases: make(map[string]Lease),
	}
	for _, opt := range opts {
		opt(m)
	}
	if m.clock == nil {
		m.clock = realClock{}
	}
	return m, nil
}

// TTL returns the lease duration configured for this Manager.
func (m *Manager) TTL() time.Duration { return m.ttl }

// Acquire takes a lease on key for owner. It fails with ErrLeaseHeld if the
// key already has an active lease. An expired lease is treated as absent and
// a fresh Token is issued.
func (m *Manager) Acquire(key, owner string) (Lease, error) {
	if key == "" {
		return Lease{}, ErrEmptyKey
	}
	if owner == "" {
		return Lease{}, ErrEmptyOwner
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	now := m.clock.Now()
	if _, ok := m.validLocked(key, now); ok {
		return Lease{}, ErrLeaseHeld
	}
	m.nextID++
	l := Lease{
		Key:       key,
		Owner:     owner,
		Token:     Token(fmt.Sprintf("tok-%d", m.nextID)),
		ExpiresAt: now.Add(m.ttl),
	}
	m.leases[key] = l
	return l, nil
}

// Renew extends the active lease on key by one ttl, measured from now. The
// owner and token must both match the active lease.
func (m *Manager) Renew(key, owner string, token Token) (Lease, error) {
	if key == "" {
		return Lease{}, ErrEmptyKey
	}
	if owner == "" {
		return Lease{}, ErrEmptyOwner
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	l, err := m.matchLocked(key, owner, token)
	if err != nil {
		return Lease{}, err
	}
	l.ExpiresAt = m.clock.Now().Add(m.ttl)
	m.leases[key] = l
	return l, nil
}

// Release drops the active lease on key. The owner and token must both match
// the active lease.
func (m *Manager) Release(key, owner string, token Token) error {
	if key == "" {
		return ErrEmptyKey
	}
	if owner == "" {
		return ErrEmptyOwner
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	if _, err := m.matchLocked(key, owner, token); err != nil {
		return err
	}
	delete(m.leases, key)
	return nil
}

// Get returns the active lease for key, or false if there is none.
func (m *Manager) Get(key string) (Lease, bool) {
	m.mu.Lock()
	defer m.mu.Unlock()
	return m.validLocked(key, m.clock.Now())
}

// Snapshot returns copies of all active leases ordered by key. The result is
// detached from the Manager's internal state.
func (m *Manager) Snapshot() []Lease {
	m.mu.Lock()
	defer m.mu.Unlock()
	now := m.clock.Now()
	out := make([]Lease, 0, len(m.leases))
	for key, l := range m.leases {
		if !l.ExpiresAt.After(now) {
			delete(m.leases, key)
			continue
		}
		out = append(out, l)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Key < out[j].Key })
	return out
}

// Len returns the number of active leases.
func (m *Manager) Len() int {
	m.mu.Lock()
	defer m.mu.Unlock()
	now := m.clock.Now()
	n := 0
	for key, l := range m.leases {
		if !l.ExpiresAt.After(now) {
			delete(m.leases, key)
			continue
		}
		n++
	}
	return n
}

// validLocked returns the active lease for key, lazily discarding an expired
// one. Callers must hold m.mu.
func (m *Manager) validLocked(key string, now time.Time) (Lease, bool) {
	l, ok := m.leases[key]
	if !ok {
		return Lease{}, false
	}
	if !l.ExpiresAt.After(now) {
		delete(m.leases, key)
		return Lease{}, false
	}
	return l, true
}

// matchLocked returns the active lease for key only when both owner and
// token match it. Callers must hold m.mu.
func (m *Manager) matchLocked(key, owner string, token Token) (Lease, error) {
	l, ok := m.validLocked(key, m.clock.Now())
	if !ok {
		return Lease{}, ErrLeaseNotFound
	}
	if l.Owner != owner {
		return Lease{}, ErrOwnerMismatch
	}
	if l.Token != token {
		return Lease{}, ErrTokenMismatch
	}
	return l, nil
}
